SELECT

FROM recommendation_log
WHERE user_id = #{userId,jdbcType=BIGINT}
AND create_time >= #{since,jdbcType=TIMESTAMP}
AND deleted = 0
ORDER BY create_time DESC

SELECT DISTINCT content_id
FROM recommendation_log
WHERE user_id = #{userId,jdbcType=BIGINT}
AND create_time >= #{since,jdbcType=TIMESTAMP}
AND deleted = 0

mapper.update:
UPDATE recommendation_log
SET is_clicked = 1,
    click_time = #{clickTime,jdbcType=TIMESTAMP},
    update_time = NOW()
WHERE user_id = #{userId,jdbcType=BIGINT}
AND content_id = #{contentId,jdbcType=BIGINT}
AND session_id = #{sessionId,jdbcType=VARCHAR}
AND is_clicked = 0
AND deleted = 0
